package com.jbrempresa.backend.repository;
import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import com.jbrempresa.backend.entity.Mensaje;
public interface MensajeRepository extends JpaRepository<Mensaje,Long>{List<Mensaje> findByEmpIdAndComIdAndMenActTrueOrderByMenSec(Long empId,Long comId);List<Mensaje> findByEmpIdAndComIdIsNullAndMenActTrueOrderByMenFecRecDesc(Long empId);Optional<Mensaje> findByEmpIdAndMenIdAndMenActTrue(Long empId,Long menId);Optional<Mensaje> findByEmpIdAndMenIdExt(Long empId,String menIdExt);Optional<Mensaje> findTopByEmpIdAndComIdAndMenDirAndMenActTrueOrderByMenSecDesc(Long empId,Long comId,String menDir);@Query("select coalesce(max(m.menSec),0)+1 from Mensaje m where m.empId=:cli and m.comId=:com")Long siguienteSecuencia(@Param("cli")Long cli,@Param("com")Long com);boolean existsByEmpIdAndMenIdExt(Long empId,String menIdExt);}
